    static ScrollViewer Scroll(object content){return new ScrollViewer {Content=content,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};}
    static TextBlock Hint(string text){return new TextBlock {Text=text,TextWrapping=TextWrapping.Wrap,Foreground=Brushes.LightSlateGray,Margin=new Thickness(0,5,0,10)};}
    static void Caption(Panel p,string title){p.Children.Add(new TextBlock {Text=title,Foreground=Brushes.MediumAquamarine,FontWeight=FontWeights.Bold,Margin=new Thickness(0,12,0,8)});}
    void Button(Panel p,string title,Action action){var b=new Button {Content=new TextBlock {Text=title,TextWrapping=TextWrapping.Wrap,TextAlignment=TextAlignment.Center}};b.Click+=(s,e)=>{if(busy)return;canvas.Finish();try{action();}catch(Exception ex){Tell(ex.Message);}};p.Children.Add(b);}
    void Field(Panel panel,string key,string title,string value){var row=new Grid {Margin=new Thickness(0,0,0,7)};row.ColumnDefinitions.Add(new ColumnDefinition {Width=new GridLength(1,GridUnitType.Star)});row.ColumnDefinitions.Add(new ColumnDefinition {Width=GridLength.Auto});var box=new TextBox {Text=value,Width=95};Grid.SetColumn(box,1);row.Children.Add(box);row.Children.Add(new TextBlock {Text=title,TextWrapping=TextWrapping.Wrap,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(0,0,6,0)});panel.Children.Add(row);fields[key]=box;box.PreviewKeyDown+=async(s,e)=>{if(e.Key==Key.Enter&&!busy){e.Handled=true;await ApplySettings();}};}
    void Set(string key,double value){fields[key].Text=value.ToString("0.###",CultureInfo.InvariantCulture);}
    double Number(string key){double n;if(!double.TryParse(fields[key].Text.Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out n)||double.IsNaN(n)||double.IsInfinity(n))throw new Exception("Некорректное число: "+key);return n;}
    int Integer(string key){double n=Number(key);if(n!=Math.Floor(n)||n>int.MaxValue||n<int.MinValue)throw new Exception("Нужно целое число: "+key);return (int)n;}
    void Tell(string text){status.Text=text;}
    void Layout(){bool narrow=middle.ActualWidth<850;middle.ColumnDefinitions[0].Width=narrow?new GridLength(1,GridUnitType.Star):new GridLength(Math.Max(290,Math.Min(370,middle.ActualWidth*.28)));middle.ColumnDefinitions[1].Width=narrow?new GridLength(0):new GridLength(1,GridUnitType.Star);middle.RowDefinitions[0].Height=narrow?new GridLength(Math.Max(90,Math.Min(190,middle.ActualHeight*.4))):new GridLength(1,GridUnitType.Star);middle.RowDefinitions[1].Height=narrow?new GridLength(1,GridUnitType.Star):new GridLength(0);Grid.SetColumn(canvas,narrow?0:1);Grid.SetRow(canvas,narrow?1:0);}
    void Push(AmbientProject value){history.Push(value);if(history.Count>24)history=new Stack<AmbientProject>(history.Take(24).Reverse());}
    void BeginGesture(){if(busy||gestureBefore!=null)return;Stop();gestureBefore=AmbientEngine.Clone(project);gestureChanged=false;}
    void EndGesture(){var before=gestureBefore;gestureBefore=null;if(before!=null&&gestureChanged)Push(before);gestureChanged=false;}
    void Changed(){revision++;cached=null;dirty=true;ScheduleGallerySave();}
    void ChangeRegion(Action<AmbientRegion> change){if(updating||busy||selected==null)return;try{var next=AmbientEngine.Clone(project);var r=next.Regions.First(v=>v.Id==selected.Id);change(r);next.Validate();if(new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(next)==new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(project))return;if(gestureBefore==null)Push(AmbientEngine.Clone(project));else gestureChanged=true;project=next;selected=r;Changed();foreach(ListBoxItem item in regions.Items){var old=item.Tag as AmbientRegion;var current=old==null?null:project.Regions.FirstOrDefault(v=>v.Id==old.Id);if(current!=null){item.Tag=current;item.Content=(current.Enabled?"● ":"○ ")+current.Name;}}SyncRegion();Preview();}catch(Exception ex){Tell(ex.Message);}}
    void Sync(){bool old=updating;updating=true;fields["Name"].Text=project.Name;Set("Width",project.Width);Set("Height",project.Height);Set("Colors",project.Colors);Set("Duration",project.Duration);Set("Fps",project.Fps);Set("OutputWidth",project.OutputWidth);Set("OutputHeight",project.OutputHeight);fields["Background"].Text=project.Background;cover.IsChecked=project.Cover;logicalPreset.SelectedIndex=0;outputPreset.SelectedIndex=0;for(int n=1;n<logicalPreset.Items.Count;n++){var p=(ResolutionPreset)logicalPreset.Items[n];if(p.Width==project.Width&&p.Height==project.Height)logicalPreset.SelectedIndex=n;}for(int n=1;n<outputPreset.Items.Count;n++){var p=(ResolutionPreset)outputPreset.Items[n];if(p.Width==project.OutputWidth&&p.Height==project.OutputHeight)outputPreset.SelectedIndex=n;}regions.Items.Clear();foreach(var r in project.Regions){var item=new ListBoxItem {Content=(r.Enabled?"● ":"○ ")+r.Name,Tag=r};regions.Items.Add(item);if(r==selected)regions.SelectedItem=item;}updating=old;SyncRegion();Preview();}
    void SyncRegion(){bool old=updating;updating=true;regionName.IsEnabled=effect.IsEnabled=enabled.IsEnabled=cycles.IsEnabled=phase.IsEnabled=selected!=null;amplitude.IsEnabled=selected!=null&&selected.Effect!=2;lightness.IsEnabled=selected!=null&&selected.Effect==2;if(selected!=null){regionName.Text=selected.Name;effect.SelectedIndex=selected.Effect;enabled.IsChecked=selected.Enabled;cycles.SelectedItem=selected.Cycles;amplitude.Value=selected.Amplitude;lightness.Value=selected.Lightness;phase.Value=selected.Phase;}amplitudeLabel.Text="Движение: "+(selected==null?0:selected.Amplitude).ToString("0.#")+" пикселя";lightLabel.Text="Изменение света: ±"+(selected==null?0:selected.Lightness).ToString("0.#")+"%";phaseLabel.Text="Сдвиг фазы: "+(selected==null?0:selected.Phase).ToString("0")+"°";updating=old;}
    void Preview(){canvas.Image=project.Base==null?null:AmbientEngine.Render(project,currentFrame/(double)project.Fps);var mask=selected==null?null:selected.Mask;if(canvas.Mask!=mask){canvas.Mask=mask;canvas.ResetMask();}canvas.ShowMask=showMask.IsChecked==true;canvas.InvalidateVisual();bool old=updating;updating=true;scrub.Maximum=Math.Max(0,project.FrameCount-1);scrub.Value=currentFrame;updating=old;timeLabel.Text="Кадр "+(currentFrame+1)+" / "+project.FrameCount+" · "+project.Width+" × "+project.Height+" → "+project.OutputWidth+" × "+project.OutputHeight+" · цикл "+project.Duration.ToString("0.###")+" с";}
    public void Stop(){clock.Stop();watch.Stop();}
    void Play(){if(project.Base==null){Tell("Загрузите фото.");return;}if(clock.IsEnabled){Stop();return;}canvas.Finish();clock.Interval=TimeSpan.FromSeconds(1.0/project.Fps);playStart=currentFrame;watch.Restart();clock.Start();}
    void Seek(int frame){Stop();currentFrame=Math.Max(0,Math.Min(project.FrameCount-1,frame));Preview();}
    void Undo(){if(busy)return;canvas.Finish();EndGesture();Stop();if(history.Count==0)return;string id=selected==null?null:selected.Id;project=history.Pop();selected=project.Regions.FirstOrDefault(r=>r.Id==id)??project.Regions.FirstOrDefault();currentFrame=Math.Min(currentFrame,project.FrameCount-1);Changed();Sync();Tell("Изменение фона отменено.");}
    void AddRegion(){if(project.Base==null)throw new Exception("Сначала загрузите фото.");if(project.Regions.Count>=32)throw new Exception("До 32 областей.");Stop();Push(AmbientEngine.Clone(project));selected=new AmbientRegion {Name="Область "+(project.Regions.Count+1),Mask=new bool[project.Width*project.Height]};project.Regions.Add(selected);Changed();Sync();side.SelectedIndex=1;Tell("Закрасьте область движения. ЛКМ — добавить, ПКМ — стереть.");}
    void DeleteRegion(){if(selected==null)return;Push(AmbientEngine.Clone(project));project.Regions.Remove(selected);selected=project.Regions.LastOrDefault();Changed();Sync();}
    void ClearMask(){if(selected==null)return;Push(AmbientEngine.Clone(project));Array.Clear(selected.Mask,0,selected.Mask.Length);selected.InvalidateMask();Changed();canvas.ResetMask();Preview();}
    void Busy(bool value){busy=value;middle.IsEnabled=!value;scrub.IsEnabled=!value;}
    async Task ApplySettings(){if(busy)return;try{Stop();canvas.Finish();var next=AmbientEngine.Clone(project);int oldW=project.Width,oldH=project.Height;next.Name=string.IsNullOrWhiteSpace(fields["Name"].Text)?"Фон из фото":fields["Name"].Text.Trim();next.Width=Integer("Width");next.Height=Integer("Height");next.Colors=Integer("Colors");next.Fps=Integer("Fps");next.Duration=Number("Duration");next.OutputWidth=Integer("OutputWidth");next.OutputHeight=Integer("OutputHeight");next.Background=fields["Background"].Text;next.Cover=cover.IsChecked==true;if(next.Width<16||next.Height<16||next.Width>640||next.Height>640)throw new Exception("Размер холста 16…640 px.");AmbientEngine.ResizeMasks(next,oldW,oldH);next.Validate();next.Duration=next.FrameCount/(double)next.Fps;bool rebuild=next.Base==null||next.Width!=oldW||next.Height!=oldH||next.Colors!=project.Colors||next.Cover!=project.Cover||next.Background!=project.Background;Busy(true);Tell("Готовлю пиксельный фон…");if(rebuild&&next.Photo!=null)next.Base=await Task.Run(()=>AmbientEngine.Pixelize(next,CancellationToken.None));Push(AmbientEngine.Clone(project));string id=selected==null?null:selected.Id;project=next;selected=project.Regions.FirstOrDefault(r=>r.Id==id);currentFrame=0;Changed();Sync();if(rebuild)canvas.Fit();Tell("Настройки применены. Добавьте области движения или экспортируйте статичный фон.");}catch(Exception ex){Tell(ex.Message);}finally{Busy(false);}}
    async Task Import(){if(busy)return;var dialog=new OpenFileDialog {Filter="Фото / изображение|*.jpg;*.jpeg;*.png;*.bmp"};if(dialog.ShowDialog()!=true)return;try{Stop();Busy(true);Tell("Загружаю фото…");var photo=Frame.Load(dialog.FileName);if((long)photo.W*photo.H>32000000)throw new Exception("Фото должно быть не больше 32 млн пикселей.");var next=AmbientEngine.Clone(project);next.Photo=photo;next.LibraryId=Guid.NewGuid().ToString("N");next.Name=Path.GetFileNameWithoutExtension(dialog.FileName);next.Regions.Clear();next.Validate();next.Base=await Task.Run(()=>AmbientEngine.Pixelize(next,CancellationToken.None));Push(AmbientEngine.Clone(project));project=next;selected=null;path=null;currentFrame=0;Changed();Sync();canvas.Fit();Tell("Фото пикселизировано. Откройте «Области движения», добавьте область и закрасьте её кистью.");}catch(Exception ex){Tell(ex.Message);}finally{Busy(false);}}
    bool Save(){Stop();canvas.Finish();if(project.Base==null)throw new Exception("Нет подготовленного фона.");var dialog=new SaveFileDialog {Filter="Проект фона|*.bgscene",FileName=path??"background.bgscene"};if(dialog.ShowDialog()!=true)return false;EnsureGalleryIdentity();AmbientFile.Save(project,dialog.FileName);ScheduleGallerySave();path=dialog.FileName;dirty=false;Tell("Фото, пиксельный фон и маски сохранены.");return true;}
    void Load(){if(!MayClose())return;var dialog=new OpenFileDialog {Filter="Проект фона|*.bgscene"};if(dialog.ShowDialog()!=true)return;var next=AmbientFile.Load(dialog.FileName);Stop();Push(AmbientEngine.Clone(project));project=next;selected=project.Regions.FirstOrDefault();path=dialog.FileName;currentFrame=0;revision++;cached=null;dirty=false;Sync();canvas.Fit();Tell("Проект фона открыт.");ScheduleGallerySave();}
    public bool MayClose(){if(busy){MessageBox.Show("Сначала завершите или отмените обработку фона.","PixelForge");return false;}if(!dirty)return true;var result=MessageBox.Show("Сохранить изменения фона из фото?","PixelForge",MessageBoxButton.YesNoCancel);if(result==MessageBoxResult.Cancel)return false;if(result==MessageBoxResult.No)return true;try{return Save();}catch(Exception ex){Tell(ex.Message);return false;}}
    async Task<List<Frame>> BuildFrames(CancellationToken token){if(project.Base==null)throw new Exception("Сначала загрузите и пикселизируйте фото.");if(cached!=null&&cacheRevision==revision)return cached;var snapshot=AmbientEngine.Clone(project);int version=revision;Tell("Собираю периодический цикл…");var result=await Task.Run(()=>AmbientEngine.Frames(snapshot,token));if(version==revision){cached=result;cacheRevision=version;}return result;}
    async Task SendToScene(){try{Stop();Busy(true);var frames=await BuildFrames(CancellationToken.None);await FlushGallery();if(Transfer!=null)Transfer(AmbientEngine.Clone(project),frames);Tell("Фон добавлен нижним слоем катсцены.");}catch(Exception ex){Tell(ex.Message);}finally{Busy(false);}}
    void ExportBase(){if(project.Base==null)throw new Exception("Нет подготовленного фона.");var dialog=new SaveFileDialog {Filter="PNG|*.png",FileName="background.png"};if(dialog.ShowDialog()==true){var scene=new Cutscene {Width=project.Width,Height=project.Height,OutputWidth=project.OutputWidth,OutputHeight=project.OutputHeight,Duration=1,Crossfade=0,Background=project.Background};scene.Layers.Add(new SceneLayer {Duration=1,Frames=new List<Frame>{project.Base}});SceneRenderer.RenderOutput(scene,0).Save(dialog.FileName);Tell("Статичный пиксельный фон сохранён: "+project.OutputWidth+" × "+project.OutputHeight);}}
    async Task Export(bool gif){try{Stop();var dialog=new SaveFileDialog {Filter=gif?"GIF|*.gif":"MP4|*.mp4",FileName=gif?"background.gif":"background.mp4"};if(dialog.ShowDialog()!=true)return;Busy(true);cancellation=new CancellationTokenSource();var frames=await BuildFrames(cancellation.Token);await FlushGallery();var scene=AmbientEngine.ToScene(project,frames);await SceneExport.Encode(scene,dialog.FileName,gif,(i,n)=>Tell("Экспорт фона "+i+" / "+n+"…"),cancellation.Token);Tell("Бесшовный цикл сохранён: "+dialog.FileName);}catch(OperationCanceledException){Tell("Экспорт отменён.");}catch(Exception ex){Tell(ex.Message);}finally{Busy(false);if(cancellation!=null){cancellation.Dispose();cancellation=null;}}}
    async Task ExportPng(){try{Stop();var dialog=new SaveFileDialog {Filter="Имя новой папки|*.folder",FileName="background_frames.folder"};if(dialog.ShowDialog()!=true)return;string dir=Path.Combine(Path.GetDirectoryName(dialog.FileName),Path.GetFileNameWithoutExtension(dialog.FileName));if(Directory.Exists(dir)&&Directory.EnumerateFileSystemEntries(dir).Any())throw new Exception("Выберите новую пустую папку.");Busy(true);cancellation=new CancellationTokenSource();var frames=await BuildFrames(cancellation.Token);await FlushGallery();var scene=AmbientEngine.ToScene(project,frames);Directory.CreateDirectory(dir);for(int n=0;n<frames.Count;n++){cancellation.Token.ThrowIfCancellationRequested();SceneRenderer.RenderOutput(scene,n/(double)scene.Fps).Save(Path.Combine(dir,"frame_"+n.ToString("D5")+".png"));Tell("PNG "+(n+1)+" / "+frames.Count);await Task.Delay(1);}File.WriteAllText(Path.Combine(dir,"animation.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new {width=scene.RenderWidth,height=scene.RenderHeight,fps=scene.Fps,frames=frames.Count,loop=true,duration=scene.Duration}));Tell("PNG-цикл экспортирован.");}catch(OperationCanceledException){Tell("Остановлено; уже записанные PNG остались в папке.");}catch(Exception ex){Tell(ex.Message);}finally{Busy(false);if(cancellation!=null){cancellation.Dispose();cancellation=null;}}}
    public async Task Demo(){if(busy)return;try{Busy(true);Stop();var next=DemoProject();next.Base=await Task.Run(()=>AmbientEngine.Pixelize(next,CancellationToken.None));Push(AmbientEngine.Clone(project));project=next;selected=project.Regions[0];currentFrame=0;path=null;Changed();Sync();canvas.Fit();side.SelectedIndex=1;Tell("Демо: вода и трава движутся, небо, горы и деревья неподвижны. Скройте маску и нажмите ▶.");}catch(Exception ex){Tell(ex.Message);}finally{Busy(false);}}
    public static AmbientProject DemoProject(){var p=new AmbientProject();var photo=new Frame(640,360);for(int y=0;y<360;y++)for(int x=0;x<640;x++){Color c=Color.FromRgb((byte)(100+y/5),(byte)(146+y/7),(byte)(180+y/8));int mountain=(int)(170+30*Math.Sin(x*.013)+20*Math.Sin(x*.031));if(y>=mountain)c=Color.FromRgb(59,91,104);if(y>210)c=Color.FromRgb(64,105,79);if(y>=226&&y<310&&x>36&&x<606)c=Color.FromRgb((byte)(47+(y%8)),(byte)(113+(y%9)),(byte)(137+(y%11)));if(y>=226&&y<310&&x>36&&x<606&&x%84>12&&x%84<54&&y%24<3)c=Color.FromRgb(83,137,155);if(y>=308)c=Color.FromRgb(51,83,53);if(y>300&&(x%19)<3)c=Color.FromRgb(97,137,72);if((x>63&&x<74&&y>157&&y<311)||(x>557&&x<569&&y>142&&y<316))c=Color.FromRgb(78,65,55);if((x-68)*(x-68)+(y-152)*(y-152)<56*56||(x-563)*(x-563)+(y-131)*(y-131)<65*65)c=Color.FromRgb(42,80,64);if((x-457)*(x-457)+(y-61)*(y-61)<20*20)c=Color.FromRgb(234,207,145);int i=(y*640+x)*4;photo.Data[i]=c.B;photo.Data[i+1]=c.G;photo.Data[i+2]=c.R;photo.Data[i+3]=255;}p.Photo=photo;p.LibraryId=Guid.NewGuid().ToString("N");p.Name="Спокойное озеро";var water=new AmbientRegion {Name="Вода",Effect=0,Amplitude=1,Cycles=1,Mask=new bool[p.Width*p.Height]};var grass=new AmbientRegion {Name="Трава",Effect=1,Amplitude=1.5,Cycles=1,Phase=90,Mask=new bool[p.Width*p.Height]};for(int y=0;y<p.Height;y++)for(int x=0;x<p.Width;x++){water.Mask[y*p.Width+x]=x>43&&x<268&&y>113&&y<153;grass.Mask[y*p.Width+x]=x>8&&x<310&&y>153&&!((x>30&&x<40)||(x>275&&x<290));}p.Regions.Add(water);p.Regions.Add(grass);return p;}
}
